function isMatured(endDateStr) {
  if (!endDateStr) return false
  const today = new Date()
  today.setHours(0, 0, 0, 0) // 오늘 00시 기준

  const endDate = new Date(endDateStr)
  endDate.setHours(0, 0, 0, 0)

  return today >= endDate   // true면 만기일 지남
}


